type Option<T> = { readonly kind: "some"; readonly value: T } | { readonly kind: "none" };
const some = <T>(value: T): Option<T> => ({ kind: "some", value });
const none: Option<never> = { kind: "none" };

function mapOption<T, U>(option: Option<T>, fn: (value: T) => U): Option<U> {
  return option.kind === "some" ? some(fn(option.value)) : none;
}

function getOrElse<T>(option: Option<T>, fallback: T): T {
  return option.kind === "some" ? option.value : fallback;
}

const discounts = new Map<string, number>([["RICE-5", 10]]);
