function partition<T, E>(results: readonly Result<T, E>[]): { readonly values: readonly T[]; readonly errors: readonly E[] } {
  const values: T[] = [];
  const errors: E[] = [];
  for (const result of results) {
    if (result.ok) values.push(result.value);
    else errors.push(result.error);
  }
  return { values, errors };
}

