type Result<T, E> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: E };

function tryCatch<T, E>(run: () => T, onError: (error: unknown) => E): Result<T, E> {
  try {
    return { ok: true, value: run() };
  } catch (error) {
    return { ok: false, error: onError(error) };
  }
}

const show = (r: Result<unknown, string>): string => (r.ok ? `ok ${String(r.value)}` : `error ${r.error}`);
const errorName = (error: unknown): string => (error instanceof Error ? error.name : "unknown");

const good = tryCatch(() => JSON.parse("0.075") as unknown, errorName);
const bad = tryCatch(() => JSON.parse("{rate:") as unknown, errorName);
console.log(`${show(good)} | ${show(bad)}`);

