type Priced =
  | { readonly kind: "item"; readonly kobo: number }
  | { readonly kind: "bundle"; readonly percentOff: number; readonly parts: readonly Priced[] };

function priceKobo(priced: Priced): number {
  switch (priced.kind) {
    case "item":
      return priced.kobo;
    case "bundle": {
      const total = priced.parts.reduce((sum, part) => sum + priceKobo(part), 0);
      return Math.round(total * (1 - priced.percentOff / 100));
    }
  }
}

